/**
 * The alternative hero motif, as bytes rather than as a file.
 *
 * It used to live in `public/`, which meant anybody could fetch it straight
 * from the site — no sequence required, just the file name. Inlined here there
 * is no URL to guess and nothing to hit: the artwork exists only inside this
 * module, and this module is only ever reached through the dynamic import in
 * the hero, so a normal visit never asks the server for it at all.
 *
 * Someone who reads the built JavaScript can still decode it. Nothing can stop
 * that — a browser cannot draw an image it is not allowed to have — but there
 * is no longer an address for it, which is what being invisible without the
 * sequence amounts to in practice.
 *
 * WebP rather than AVIF: a third larger, and supported by everything back to
 * Safari 14. A broken image is a worse joke than a slightly larger chunk that
 * only the initiated ever download.
 *
 * 900px square at quality 82, from the artwork described in ./index.tsx.
 * Regenerate with sharp: .resize(900, 900, { kernel: 'lanczos3' })
 * .webp({ quality: 82, effort: 6 }), then base64.
 */
// prettier-ignore
export const ARTWORK =
  'data:image/webp;base64,'
